import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

router.post('/parse-resume', upload.single('resume'), async (req: MulterRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume file provided' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const extractedText = pdfData.text;

    res.status(200).json({
      success: true,
      filename: req.file.originalname,
      numpages: pdfData.numpages,
      text: extractedText,
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF file', details: error.message });
  }
});

export default router;

import React, { useState, useMemo } from 'react';

interface KeywordMatchResult {
  score: number;
  matched: string[];
  missing: string[];
}

export const useKeywordMatcher = (resumeText: string, jobDescription: string): KeywordMatchResult => {
  return useMemo(() => {
    if (!jobDescription || !resumeText) return { score: 0, matched: [], missing: [] };

    const cleanWords = (text: string) =>
      Array.from(new Set(text.toLowerCase().match(/\b[a-z]{3,}\b/g) || []));

    const jobKeywords = cleanWords(jobDescription);
    const resumeLower = resumeText.toLowerCase();

    const matched: string[] = [];
    const missing: string[] = [];

    jobKeywords.forEach(kw => {
      if (resumeLower.includes(kw)) {
        matched.push(kw);
      } else {
        missing.push(kw);
      }
    });

    const score = jobKeywords.length > 0 ? Math.round((matched.length / jobKeywords.length) * 100) : 0;
    return { score, matched, missing };
  }, [resumeText, jobDescription]);
};

export const MatchBreakdownDisplay: React.FC<{ score: number; matched: string[]; missing: string[] }> = ({ score, matched, missing }) => (
  <div className="p-6 bg-white rounded-xl shadow-md space-y-4">
    <div className="flex items-center justify-between">
      <h3 className="text-lg font-bold text-gray-800">Match Score</h3>
      <span className={`text-2xl font-extrabold ${score >= 70 ? 'text-green-600' : 'text-amber-500'}`}>{score}%</span>
    </div>
    <div className="w-full bg-gray-200 rounded-full h-3">
      <div className="bg-blue-600 h-3 rounded-full transition-all duration-500" style={{ width: `${score}%` }}></div>
    </div>
    <div className="grid grid-cols-2 gap-4 pt-2">
      <div>
        <h4 className="font-semibold text-green-700 text-sm mb-2">Matched Keywords ({matched.length})</h4>
        <div className="flex flex-wrap gap-1">
          {matched.map(kw => <span key={kw} className="px-2 py-1 bg-green-50 text-green-700 text-xs rounded-md">{kw}</span>)}
        </div>
      </div>
      <div>
        <h4 className="font-semibold text-red-700 text-sm mb-2">Missing Keywords ({missing.length})</h4>
        <div className="flex flex-wrap gap-1">
          {missing.map(kw => <span key={kw} className="px-2 py-1 bg-red-50 text-red-700 text-xs rounded-md">{kw}</span>)}
        </div>
      </div>
    </div>
  </div>
);
